import{z as i,x as n,o as e,c as s,q as B,j as l,D as E,d as A,s as r,S as o}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"端侧评测","description":"","frontmatter":{"title":"端侧评测","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/edge-eval.md","filePath":"llm/edge-eval.md","lastUpdated":1791063341000}'),d={name:"llm/edge-eval.md"};function p(m,a,T,F,_,h){const t=n("Mermaid");return e(),s("div",null,[a[2]||(a[2]=B('<h1 id="端侧评测" tabindex="-1">端侧评测 <a class="header-anchor" href="#端侧评测" aria-label="Permalink to &quot;端侧评测&quot;">​</a></h1><div class="epigraph"><p>端侧评测要答两个问题：模型对不对，机器扛不扛得住；只答第一个的评测，在端侧等于没测。</p><footer>—— 据 MLCommons MLPerf Mobile 与端侧基准实践口径整理</footer></div><p><a href="/llm/edge-privacy-localization">上一课</a>把数据等级接进路由，产品形态已齐：模型、预算、路由、隐私都定了，上线前剩一道闸——评测。云端评测主要答「质量与吞吐」；端侧多出三个维度：延迟的分位、资源的峰值、热节流后的持续性，而且质量本身也要重测：量化与设备端数值路径都会移动输出分布。本课写这张二维试卷怎么出、怎么考、怎么判卷。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>质量侧：同一份权重，fp16 与 4-bit 在同一任务集上不是同一个模型；不同后端——CPU、GPU、NPU——的累加顺序与精度也不同。退化要用<a href="/llm/quant-error-metrics">量化误差度量</a>的指标对 fp16 基线量化，形态对照<a href="/llm/quant-eval-degradation">量化后退化模式</a>识别；长尾任务先坏是常见形态，平均分盖不住它。资源侧：TTFT 要把模型加载与预热分开计，TPOT 取稳态分位，峰值 RSS 与毫瓦时每千 token 各占一行。<span class="marginnote">TTFT 是 time to first token：从发请求到吐出第一个字的时间，决定「响应快不快」的体感；TPOT 是 time per output token：之后每个字之间的平均间隔，决定「打字机快不快」。两者必须分开报——模型加载拖慢的是 TTFT、不影响 TPOT，混成一个平均数就再也找不到问题出在哪一段。</span>持续性侧：冷启动跑分是峰值幻觉，热节流让第一分钟与第十分钟差数倍——不测长跑等于没测 decode。</p><h3 id="评测矩阵" tabindex="-1">评测矩阵 <a class="header-anchor" href="#评测矩阵" aria-label="Permalink to &quot;评测矩阵&quot;">​</a></h3><p>设备档位、后端、量化配置、场景——冷启动、稳态、长会话——四个轴各取代表点；矩阵不必全积，但每个档位的旗舰与低端都要覆盖。控制变量三件：环境温度、电量段、后台负载。真机优先，模拟器只做功能验证：模拟器的数值路径、内存压力与 DVFS 行为都不是目标设备的行为。</p>',7)),(e(),l(o,null,{default:E(()=>[r(t,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E8%AF%84%E6%B5%8B%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20Q%5B%22%E8%B4%A8%E9%87%8F%3A%20%E5%9B%B0%E6%83%91%E5%BA%A6%20%E5%8A%A0%E4%BB%BB%E5%8A%A1%E9%9B%86%20%E5%AF%B9%20fp16%20%E5%9F%BA%E7%BA%BF%22%5D%0A%20%20M%20--%3E%20P%5B%22%E5%BB%B6%E8%BF%9F%3A%20TTFT%20%E5%88%86%E6%AE%B5%20%E5%8A%A0%20TPOT%20%E7%A8%B3%E6%80%81%E5%88%86%E4%BD%8D%22%5D%0A%20%20M%20--%3E%20R%5B%22%E8%B5%84%E6%BA%90%3A%20%E5%B3%B0%E5%80%BC%20RSS%20%E5%8A%A0%E6%AF%AB%E7%93%A6%E6%97%B6%E6%AF%8F%E5%8D%83%20token%22%5D%0A%20%20M%20--%3E%20S%5B%22%E6%8C%81%E7%BB%AD%3A%20%E9%95%BF%E8%B7%91%E8%A1%B0%E5%87%8F%E6%9B%B2%E7%BA%BF%22%5D%0A%20%20Q%20--%3E%20G%7B%22%E9%97%A8%E7%A6%81%22%7D%0A%20%20P%20--%3E%20G%0A%20%20R%20--%3E%20G%0A%20%20S%20--%3E%20G%0A%20%20G%20--%3E%7C%E8%BF%87%7C%20SHIP%5B%22%E8%BF%9B%E5%8F%91%E5%B8%83%22%5D%0A%20%20G%20--%3E%7C%E4%B8%8D%E8%BF%87%7C%20FIX%5B%22%E6%8B%A6%E4%B8%8B%E5%BD%92%E5%9B%A0%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>判卷靠配置串：设备型号、系统版本、运行时版本、模型哈希、量化配置、线程与后端绑定——缺一项的数字不可比也不可复现，端侧评测的公信力全在这串里。分数取分位不取均值：TTFT 报 P50 与 P90，长跑报速率衰减曲线而不是平均速率。质量与资源放同一张表判：一个「快但变笨」的量化配置和一个「聪明但撑不过十分钟」的配置，都过不了门禁。阈值由上一版发布物定基线：判相对回归，不判绝对值。<span class="marginnote">初学者容易用平均延迟判断体验好坏，实际用户对「偶尔卡一下」极其敏感：P50 是 200 毫秒、P90 却是 2 秒的服务，平均值看着体面，但每十次请求就有一次明显卡顿。报分位（P50/P90）而不是均值，就是把「最差的那批体验」逼到台面上——平均值会体面地藏起它。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么门禁要挂在发布流程上（下一课展开）：设备碎片化让实验室矩阵永远盖不全长尾，能守住的是「已知配置不回退」，长尾交给灰度遥测。为什么质量要在真机复测而不只信云端同款：后端数值路径不同，采样行为的差异在长生成里被放大，云端测过的任务集在端上重跑，常能抓出「平均分没掉、长答案先坏」的配置。评测对开发的接口是「可复现的配置串加分位数」：工程师拿到一条失败，能在自己桌上重放出同一条曲线，评测才有工程价值。</p><p><span class="marginnote">报告里「Q4 8B 在某机型每秒 12 token」这种句子必须带完整配置串与环境温度，否则无法复现——同一台机器冬夏之间、不同后台负载下能差出三成。</span></p><p>一条配置串如何支撑「失败可重放」：</p>',6)),(e(),l(o,null,{default:E(()=>[r(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20RUN%5B%22%E4%B8%80%E6%AC%A1%E7%AB%AF%E4%BE%A7%E8%AF%84%E6%B5%8B%E8%BF%90%E8%A1%8C%22%5D%20--%3E%20CFG%5B%22%E9%85%8D%E7%BD%AE%E4%B8%B2%22%5D%0A%20%20CFG%20--%3E%20C1%5B%22%E8%AE%BE%E5%A4%87%E5%9E%8B%E5%8F%B7%20%2B%20%E7%B3%BB%E7%BB%9F%E7%89%88%E6%9C%AC%22%5D%0A%20%20CFG%20--%3E%20C2%5B%22%E8%BF%90%E8%A1%8C%E6%97%B6%20%2B%20%E5%90%8E%E7%AB%AF%E4%B8%8E%E7%BA%BF%E7%A8%8B%E7%BB%91%E5%AE%9A%22%5D%0A%20%20CFG%20--%3E%20C3%5B%22%E6%A8%A1%E5%9E%8B%E5%93%88%E5%B8%8C%20%2B%20%E9%87%8F%E5%8C%96%E9%85%8D%E7%BD%AE%22%5D%0A%20%20C1%20--%3E%20RE%5B%22%E4%BB%96%E4%BA%BA%E6%8C%89%E4%B8%B2%E9%87%8D%E5%BB%BA%E7%8E%AF%E5%A2%83%22%5D%0A%20%20C2%20--%3E%20RE%0A%20%20C3%20--%3E%20RE%0A%20%20RE%20--%3E%20SAME%5B%22%E9%87%8D%E6%94%BE%E5%87%BA%E5%90%8C%E4%B8%80%E6%9D%A1%E5%88%86%E4%BD%8D%E6%9B%B2%E7%BA%BF%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<p><span class="marginnote">为什么长尾交给灰度遥测？实验室矩阵像考前押题，只能覆盖代表性机型；灰度发布后成千上万台真实设备自动替你考完整张卷子——温度、电量、后台负载的组合实验室永远造不全。分工由此清楚：门禁守住「已知配置不回退」，遥测去抓未知的坑，两者缺一不可。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不测竞品排行：那是市场口径，不是回归口径。评测不能替代灰度与线上遥测，后者是免费的真机矩阵。用户感知延迟与毫秒数的关系（什么算「卡」）是产品题，本课只供分位数据。基准集污染与刷榜的防排在主干评测各课，本课只补端侧维度。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>两个问题都要答：质量对不对、机器扛不扛得住；长跑与分位是端侧必答题。</li><li>质量在真机对 fp16 基线复测，退化按形态识别，平均分会掩盖长尾先坏。</li><li>判卷靠配置串：型号、系统、运行时、模型哈希、量化配置缺一不可。</li><li>门禁以上一版为基线判相对回归，挂进发布流程。</li><li>出处：MLCommons MLPerf Mobile 口径；本站量化误差度量与量化后退化模式课；按本课程实测方法整理。</li></ul>',5))])}const c=i(d,[["render",p]]);export{C as __pageData,c as default};
